// SwaggerInfoeduapi holds exported Swagger Info so clients can modify it
var SwaggerInfoeduapi = &swag.Spec{
	Version:          "1.0",
	Host:             "",
	BasePath:         "/1edtech/eduapi/base/v1p0",
	Schemes:          []string{},
	Title:            "SIS Edu-API v1.0",
	Description:      "Read-only publication of the SIS data in 1EdTech Edu-API v1.0 (Final) shapes.\n\nEvery endpoint needs a Bearer access token from one of the token issuers\nSIS trusts (sis.auth.issuers), with scope sis.read or the spec's\nhttp://purl.1edtech.org/spec/eduapi/v1p0/scope/core.readonly.\n\nLists are bare JSON arrays. X-Total-Count holds the number of stored\nrecords and Link the first, prev, next and last pages. A record is\naddressed by its sourcedId, and references between records are\nsourcedIds. Errors use the spec's Imsx_StatusInfo body. Lists that\nsupport sort and filter say so; the others answer 400.\n\nSIS stores less than the spec requires, so a required field with no data\nis filled in one of three ways. Free text (title, description) falls back\nto the record's own title, then its course title or sourcedId. An\nenumeration carries the extensible term ext:unspecified, except\nregistrationStatus, which is always closed. References and dates are\nomitted rather than invented, so a client can receive a record without them.",
	InfoInstanceName: "eduapi",
	SwaggerTemplate:  docTemplateeduapi,
	LeftDelim:        "{{",
	RightDelim:       "}}",
}

func init() {
	swag.Register(SwaggerInfoeduapi.InstanceName(), SwaggerInfoeduapi)
}
